  // Верните { margin, remainder } — маржа на единицу и остаток периода,
  // остаток округлён до одного знака после запятой.
  // Любой нечисловой вход или отрицательный (кроме sales >= 0) -> null.
}

practice.solution:
function contribution(price, variable, fixed, invisible, sales) {
  const nums = [price, variable, fixed, invisible, sales];
  if (!nums.every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  if (price <= 0 || variable < 0 || fixed < 0 || invisible < 0 || sales < 0) return null;
  const margin = price - variable;
  const remainder = Math.round((margin * sales - fixed - invisible) * 10) / 10;
  return { margin, remainder };
}

demo.code:
contribution(4, 0.5, 2, 0.6, 10);
// margin: 4 - 0.5 = 3.5
// remainder: 3.5 * 10 - 2 - 0.6 = 32.4
contribution(4, 0.5, 2, 0.6, 0);
// remainder: 0 - 2.6 = -2.6 (убыток, не null)

