  // Верните { margin, cac, ltv, ratio, status } — все деньги округлены
  // до одного знака; ratio = ltv / cac при cac > 0, иначе null.
  // Нечисловой или отрицательный вход (кроме retention >= 0) -> null.
}

practice.solution:
function unitEconomics(price, variable, retention, cac, status) {
  const nums = [price, variable, retention, cac];
  if (!nums.every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  if (price <= 0 || variable < 0 || retention < 0 || cac < 0) return null;
  const margin = price - variable;
  const ltv = Math.round(margin * retention * 10) / 10;
  const ratio = cac > 0 ? Math.round(ltv / cac * 10) / 10 : null;
  return { margin, cac, ltv, ratio, status };
}

demo.code:
