// margin: 4 - 0.5 = 3.5
// ltv: 3.5 * 3 = 10.5
// ratio: 10.5 / 0.3 = 35
unitEconomics(4, 0.5, 3, 0, 'estimated');
// ratio: null (деление на ноль CAC запрещено)

