function monthSalesNeeded(margin, fixed, months, target) {
  // Верните массив длины months — ровное число продаж в месяц:
  // Math.ceil((fixed * months + target) / margin).
  // margin <= 0, target < 0, месяцы не целые или < 1, нечисловой вход -> null.
}

practice.solution:
function monthSalesNeeded(margin, fixed, months, target) {
  const nums = [margin, fixed, months, target];
  if (!nums.every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  if (margin <= 0 || fixed < 0 || target < 0) return null;
  if (!Number.isInteger(months) || months < 1) return null;
  const per = Math.ceil((fixed * months + target) / margin);
  return Array(months).fill(per);
}
